<?php
// ============================================================
//  GENERATED BY build.pl — edit build.pl, not this file.
//
//  Reads the projects the dashboard owns. Every function fails
//  soft: if the database is unreachable the pages still render,
//  just without projects, because a visitor should never meet a
//  stack trace.
// ============================================================
require_once __DIR__ . '/../admin/lib.php';

function aqm_rows(string $skip = ''): array {
  $pdo = db(true);
  if (!$pdo) return [];
  try {
    if ($skip !== '') {
      $st = $pdo->prepare('SELECT * FROM projects WHERE status = "live" AND slug <> ? ORDER BY sort, id');
      $st->execute([$skip]);
    } else {
      $st = $pdo->query('SELECT * FROM projects WHERE status = "live" ORDER BY sort, id');
    }
    return $st->fetchAll();
  } catch (Throwable $e) {
    return [];
  }
}

function aqm_one(string $slug): ?array {
  $pdo = db(true);
  if (!$pdo || $slug === '') return null;
  try {
    $st = $pdo->prepare('SELECT * FROM projects WHERE slug = ? AND status = "live" LIMIT 1');
    $st->execute([$slug]);
    $row = $st->fetch();
    return $row ?: null;
  } catch (Throwable $e) {
    return null;
  }
}

function aqm_images(int $id): array {
  $pdo = db(true);
  if (!$pdo) return [];
  try {
    $st = $pdo->prepare('SELECT * FROM project_images WHERE project_id = ? ORDER BY sort, id');
    $st->execute([$id]);
    return $st->fetchAll();
  } catch (Throwable $e) {
    return [];
  }
}

// The project before and after this one, in the order the dashboard sets.
function aqm_around(array $rows, string $slug): array {
  $i = -1;
  foreach ($rows as $k => $r) { if ($r['slug'] === $slug) { $i = $k; break; } }
  if ($i < 0) return [null, null];
  return [$i > 0 ? $rows[$i - 1] : null, $i < count($rows) - 1 ? $rows[$i + 1] : null];
}

function aqm_txt(array $p, string $field, string $lang): string {
  return (string) ($p[$field . '_' . ($lang === 'en' ? 'en' : 'ar')] ?? '');
}

// One card, the same shape proj_cards() builds for the home page.
function aqm_cards(array $rows, string $lang, string $a, string $view, string $icon,
                   string $cls = 'proj-grid', string $id = ''): string {
  $o = '<div class="' . $cls . '"' . ($id !== '' ? ' id="' . $id . '"' : '') . '>';
  $n = 0;
  foreach ($rows as $p) {
    $t = aqm_txt($p, 'title', $lang);
    $d = aqm_txt($p, 'lead', $lang);
    $delay = number_format(($n % 3) * 0.09, 2);
    $o .= '<a class="proj" href="project.php?slug=' . urlencode($p['slug']) . '"'
        . ' data-cat="' . h($p['sec']) . '" data-rv data-delay="' . $delay . '">'
        . '<img src="' . $a . 'assets/img/' . h($p['cover']) . '" alt="' . h($t) . '" loading="lazy">'
        . '<div class="proj-in"><span class="tag">' . h($p['tag']) . '</span>'
        . '<h3>' . h($t) . '</h3><p>' . h($d) . '</p>'
        . '<span class="go">' . h($view) . ' ' . $icon . '</span></div></a>';
    $n++;
  }
  return $o . '</div>';
}

// How many live projects sit in each sector, for the filter chips.
function aqm_counts(array $rows): array {
  $c = ['residential' => 0, 'commercial' => 0, 'hospitality' => 0, 'industrial' => 0];
  foreach ($rows as $r) { if (isset($c[$r['sec']])) $c[$r['sec']]++; }
  return $c;
}

// A fact with nothing in it is left out rather than shown empty.
function aqm_facts(array $pairs): string {
  $o = '<dl class="facts" data-rv>';
  foreach ($pairs as $r) {
    if ((string) $r[1] === '') continue;
    $o .= '<div class="fact"><dt>' . h($r[0]) . '</dt><dd>' . h($r[1]) . '</dd></div>';
  }
  return $o . '</dl>';
}

// The long text is one scope line per line; an empty one falls back to
// the standard scope the site shows for a project with no detail yet.
function aqm_scope(string $body, array $fallback): string {
  $lines = [];
  foreach (preg_split('/\r?\n/', $body) as $l) {
    $l = trim($l);
    if ($l !== '') $lines[] = $l;
  }
  if (!$lines) $lines = $fallback;
  $o = '<ol class="scope" data-rv>';
  foreach ($lines as $l) $o .= '<li>' . h($l) . '</li>';
  return $o . '</ol>';
}

function aqm_gallery(array $imgs, string $a, string $lang, string $cap, string $zoom, string $icon): string {
  if (!$imgs) return '';
  $o = '<div class="strip">';
  $n = 0;
  foreach ($imgs as $i) {
    $c = (string) ($i['caption_' . ($lang === 'en' ? 'en' : 'ar')] ?? '');
    if ($c === '') $c = $cap;
    $src = $a . 'assets/img/' . h($i['file']);
    $o .= '<figure data-full="' . $src . '" data-cap="' . h($c) . '" data-rv data-delay="'
        . number_format($n * 0.07, 2) . '" aria-label="' . h($zoom) . '">'
        . '<img src="' . $src . '" alt="' . h($c) . '" loading="lazy">'
        . '<figcaption>' . $icon . '</figcaption></figure>';
    $n++;
  }
  return $o . '</div>';
}

function aqm_pager(?array $prev, ?array $next, string $lang, string $prevLabel,
                   string $nextLabel, string $backIcon, string $fwdIcon): string {
  $o = '<nav class="pager">';
  $o .= $prev
    ? '<a class="prev" href="project.php?slug=' . urlencode($prev['slug']) . '">' . $backIcon
      . '<span><span class="lbl">' . h($prevLabel) . '</span>'
      . '<span class="ttl">' . h(aqm_txt($prev, 'title', $lang)) . '</span></span></a>'
    : '<a class="prev empty" href="#"><span></span></a>';
  $o .= $next
    ? '<a class="next" href="project.php?slug=' . urlencode($next['slug']) . '">'
      . '<span><span class="lbl">' . h($nextLabel) . '</span>'
      . '<span class="ttl">' . h(aqm_txt($next, 'title', $lang)) . '</span></span>' . $fwdIcon . '</a>'
    : '<a class="next empty" href="#"><span></span></a>';
  return $o . '</nav>';
}
